// swift-tools-version:6.2
//
// The macOS client. Built by scripts/build-macos.sh, which first compiles the
// Rust core (crates/riff-ffi) and generates its Swift bindings into
// Sources/RiffFFI and Sources/RiffCore.

import PackageDescription

let rustLibDir = Context.environment["RIFF_RUST_LIB_DIR"] ?? "../target/release"

let package = Package(
    name: "Riff",
    defaultLocalization: "en",
    platforms: [.macOS(.v26)],
    products: [
        .executable(name: "Riff", targets: ["Riff"]),
    ],
    targets: [
        // C header and module map generated by UniFFI.
        .target(
            name: "riff_ffiFFI",
            path: "Sources/RiffFFI"
        ),
        // Generated Swift bindings for the Rust core.
        .target(
            name: "RiffCore",
            dependencies: ["riff_ffiFFI"],
            path: "Sources/RiffCore",
            swiftSettings: [.swiftLanguageMode(.v5)],
            linkerSettings: [
                .unsafeFlags(["-L", rustLibDir]),
                .linkedLibrary("riff_ffi"),
                .linkedFramework("Security"),
                .linkedFramework("SystemConfiguration"),
                .linkedFramework("CoreAudio"),
                .linkedFramework("AudioToolbox"),
                .linkedFramework("AudioUnit"),
                .linkedFramework("CoreFoundation"),
            ]
        ),
        .executableTarget(
            name: "Riff",
            dependencies: ["RiffCore"],
            path: "Sources/Riff",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
        .testTarget(
            name: "RiffTests",
            dependencies: ["Riff"],
            path: "Tests/RiffTests",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
    ]
)
